<?php require __DIR__.'/_head.php';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=$_POST['action']??'';
if($action==='delete'){$s=$pdo->prepare('DELETE FROM products WHERE id=?');$s->execute([(int)$_POST['id']]);flash('পণ্য মুছে ফেলা হয়েছে।');header('Location: '.url('admin/products.php'));exit;}
$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');$price=trim($_POST['price']??'');$cat=(int)($_POST['category_id']??0);$active=isset($_POST['is_active'])?1:0;
if($name){$image=$_POST['old_image']??'assets/pacifier.jpg';if(!empty($_FILES['image']['name'])&&is_uploaded_file($_FILES['image']['tmp_name'])){$ext=strtolower(pathinfo($_FILES['image']['name'],PATHINFO_EXTENSION));if(in_array($ext,['jpg','jpeg','png','webp'])){$fn='p_'.bin2hex(random_bytes(8)).'.'.$ext;move_uploaded_file($_FILES['image']['tmp_name'],UPLOAD_DIR.$fn);$image=UPLOAD_URL.$fn;}}
$val=$price===''?null:(float)$price;
if($id){$s=$pdo->prepare('UPDATE products SET name=?,description=?,price=?,category_id=?,image=?,is_active=? WHERE id=?');$s->execute([$name,$desc,$val,$cat?:null,$image,$active,$id]);}else{$s=$pdo->prepare('INSERT INTO products(name,description,price,category_id,image,is_active,created_at) VALUES(?,?,?,?,?,?,NOW())');$s->execute([$name,$desc,$val,$cat?:null,$image,$active]);}flash('পণ্য সংরক্ষণ হয়েছে।');}
header('Location: '.url('admin/products.php'));exit;}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$cats=$pdo->query('SELECT * FROM categories')->fetchAll();$products=$pdo->query('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC')->fetchAll();?>
<div class="card"><h2><?= $edit?'পণ্য সম্পাদনা':'নতুন পণ্য যোগ করুন' ?></h2><form method="post" enctype="multipart/form-data" class="form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><input type="hidden" name="old_image" value="<?=e($edit['image']??'assets/pacifier.jpg')?>"><input name="name" required placeholder="পণ্যের নাম" value="<?=e($edit['name']??'')?>"><textarea name="description" placeholder="বিবরণ"><?=e($edit['description']??'')?></textarea><input type="number" step="0.01" min="0" name="price" placeholder="দাম (খালি রাখলে পরে নিশ্চিত হবে)" value="<?=e($edit['price']??'')?>"><select name="category_id"><option value="">ক্যাটাগরি</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=isset($edit['category_id'])&&$edit['category_id']==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><input type="file" name="image" accept=".jpg,.jpeg,.png,.webp"><label><input type="checkbox" name="is_active" <?=!isset($edit)||($edit['is_active']??0)?'checked':''?>> সক্রিয়</label><button class="btn">সংরক্ষণ</button></form></div>
<div class="card"><h2>সব পণ্য</h2><div class="table-wrap"><table><tr><th>নাম</th><th>ক্যাটাগরি</th><th>দাম</th><th>অ্যাকশন</th></tr><?php foreach($products as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['category_name']??'')?></td><td><?=$p['price']===null?'পরে নির্ধারণ':money($p['price'])?></td><td><a href="?edit=<?=$p['id']?>">সম্পাদনা</a> <form method="post" class="inline" onsubmit="return confirm('মুছে ফেলবেন?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn danger">ডিলিট</button></form></td></tr><?php endforeach;?></table></div></div>
<?php require __DIR__.'/_foot.php';?>
